import base64
import hashlib
import hmac
import os
import re
from typing import Optional

from argon2 import PasswordHasher, exceptions as argon2_exceptions

# Constants and configuration per current OWASP Password Storage Cheat Sheet (2026-05-12)

# Argon2id recommended minimum config for new hashes:
# m=19456 KiB (19 MiB), t=2 iterations, p=1 parallelism
ARGON2_MEMORY_COST = 19456  # in kibibytes
ARGON2_TIME_COST = 2
ARGON2_PARALLELISM = 1

# scrypt recommended minimum config if Argon2id unavailable:
# N=2^17 (131072), r=8, p=1
SCRYPT_N = 2 ** 17
SCRYPT_R = 8
SCRYPT_P = 1
SCRYPT_DKLEN = 64  # derived key length in bytes

# bcrypt legacy config:
BCRYPT_WORK_FACTOR = 10
BCRYPT_MAX_PASSWORD_LENGTH = 72  # bytes

# PBKDF2 recommended config for FIPS-140 compliance:
# HMAC-SHA256, 600,000 iterations
PBKDF2_ITERATIONS = 600_000
PBKDF2_HASH_NAME = "sha256"
PBKDF2_DKLEN = 32  # bytes

# Legacy PBKDF2-HMAC-SHA1 (legacy only, do not use for new hashes)
PBKDF2_SHA1_ITERATIONS = 1_400_000
PBKDF2_SHA1_HASH_NAME = "sha1"
PBKDF2_SHA1_DKLEN = 20

# Legacy bcrypt prefix for detection
BCRYPT_PREFIXES = (b"$2a$", b"$2b$", b"$2y$")

# Legacy PBKDF2 prefix for detection
PBKDF2_PREFIX = "pbkdf2_sha256$"
PBKDF2_SHA1_PREFIX = "pbkdf2_sha1$"

# Legacy scrypt prefix for detection
SCRYPT_PREFIX = "scrypt$"

# Argon2id prefix for detection
ARGON2ID_PREFIX = "argon2id$"

# We have argon2-cffi installed, so we will use Argon2id for new hashes.
# If Argon2id unavailable, fallback to scrypt.
# Legacy bcrypt and PBKDF2 hashes must still verify.

# Pepper is optional and not specified in the request, so we do not use pepper here.

# Argon2id PasswordHasher instance with recommended config for new hashes
argon2_hasher = PasswordHasher(
    time_cost=ARGON2_TIME_COST,
    memory_cost=ARGON2_MEMORY_COST,
    parallelism=ARGON2_PARALLELISM,
    hash_len=32,
    salt_len=16,
    encoding="utf-8",
)

# Helper functions for scrypt encoding/decoding and hash formatting


def _b64encode(data: bytes) -> str:
    return base64.b64encode(data).decode("ascii")


def _b64decode(data: str) -> bytes:
    return base64.b64decode(data.encode("ascii"))


def _format_scrypt_hash(
    salt: bytes, n: int, r: int, p: int, dk: bytes
) -> str:
    # Format: scrypt$N$r$p$salt$dk
    # All base64 encoded except N,r,p as integers
    return "scrypt${}${}${}${}${}".format(
        n,
        r,
        p,
        _b64encode(salt),
        _b64encode(dk),
    )


def _parse_scrypt_hash(stored: str):
    # Parse scrypt$N$r$p$salt$dk
    try:
        parts = stored.split("$")
        if len(parts) != 7 or parts[0] != "scrypt":
            return None
        _, n_str, r_str, p_str, salt_b64, dk_b64 = parts
        n = int(n_str)
        r = int(r_str)
        p = int(p_str)
        salt = _b64decode(salt_b64)
        dk = _b64decode(dk_b64)
        return n, r, p, salt, dk
    except Exception:
        return None


def _format_pbkdf2_hash(
    hash_name: str, iterations: int, salt: bytes, dk: bytes
) -> str:
    # Format: pbkdf2_<hash_name>$iterations$salt$dk
    # salt and dk base64 encoded
    return "pbkdf2_{}${}${}${}".format(
        hash_name,
        iterations,
        _b64encode(salt),
        _b64encode(dk),
    )


def _parse_pbkdf2_hash(stored: str):
    # Parse pbkdf2_<hash_name>$iterations$salt$dk
    try:
        if not stored.startswith("pbkdf2_"):
            return None
        parts = stored.split("$")
        if len(parts) != 4:
            return None
        algo = parts[0][7:]  # after pbkdf2_
        iterations = int(parts[1])
        salt = _b64decode(parts[2])
        dk = _b64decode(parts[3])
        return algo, iterations, salt, dk
    except Exception:
        return None


def _is_bcrypt_hash(stored: str) -> bool:
    # bcrypt hashes start with $2a$, $2b$, or $2y$
    if not stored:
        return False
    stored_bytes = stored.encode("utf-8")
    return any(stored_bytes.startswith(prefix) for prefix in BCRYPT_PREFIXES)


def _bcrypt_verify(password: str, stored_hash: str) -> bool:
    import bcrypt

    try:
        # bcrypt expects bytes password
        password_bytes = password.encode("utf-8")
        stored_bytes = stored_hash.encode("utf-8")
        return bcrypt.checkpw(password_bytes, stored_bytes)
    except Exception:
        return False


def _bcrypt_hash(password: str, work_factor: int = BCRYPT_WORK_FACTOR) -> str:
    import bcrypt

    password_bytes = password.encode("utf-8")
    if len(password_bytes) > BCRYPT_MAX_PASSWORD_LENGTH:
        # bcrypt truncates input to 72 bytes, so we reject longer passwords
        raise ValueError(
            f"Password too long for bcrypt (max {BCRYPT_MAX_PASSWORD_LENGTH} bytes)"
        )
    salt = bcrypt.gensalt(rounds=work_factor)
    hashed = bcrypt.hashpw(password_bytes, salt)
    return hashed.decode("utf-8")


def _argon2id_hash(password: str) -> str:
    # argon2-cffi PasswordHasher returns encoded string with prefix argon2id$
    return argon2_hasher.hash(password)


def _argon2id_verify(password: str, stored_hash: str) -> bool:
    try:
        argon2_hasher.verify(stored_hash, password)
        return True
    except argon2_exceptions.VerifyMismatchError:
        return False
    except Exception:
        return False


def _scrypt_hash(password: str) -> str:
    salt = os.urandom(16)
    dk = hashlib.scrypt(
        password.encode("utf-8"),
        salt=salt,
        n=SCRYPT_N,
        r=SCRYPT_R,
        p=SCRYPT_P,
        dklen=SCRYPT_DKLEN,
    )
    return _format_scrypt_hash(salt, SCRYPT_N, SCRYPT_R, SCRYPT_P, dk)


def _scrypt_verify(password: str, stored_hash: str) -> bool:
    parsed = _parse_scrypt_hash(stored_hash)
    if parsed is None:
        return False
    n, r, p, salt, dk = parsed
    try:
        computed_dk = hashlib.scrypt(
            password.encode("utf-8"), salt=salt, n=n, r=r, p=p, dklen=len(dk)
        )
        return hmac.compare_digest(computed_dk, dk)
    except Exception:
        return False


def _pbkdf2_hash(password: str) -> str:
    salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac(
        PBKDF2_HASH_NAME,
        password.encode("utf-8"),
        salt,
        PBKDF2_ITERATIONS,
        dklen=PBKDF2_DKLEN,
    )
    return _format_pbkdf2_hash(PBKDF2_HASH_NAME, PBKDF2_ITERATIONS, salt, dk)


def _pbkdf2_verify(password: str, stored_hash: str) -> bool:
    parsed = _parse_pbkdf2_hash(stored_hash)
    if parsed is None:
        return False
    algo, iterations, salt, dk = parsed
    try:
        computed_dk = hashlib.pbkdf2_hmac(
            algo, password.encode("utf-8"), salt, iterations, dklen=len(dk)
        )
        return hmac.compare_digest(computed_dk, dk)
    except Exception:
        return False


def _pbkdf2_sha1_verify(password: str, stored_hash: str) -> bool:
    # Legacy PBKDF2-HMAC-SHA1 hashes start with pbkdf2_sha1$
    # We parse and verify similarly to pbkdf2_sha256 but with sha1 and legacy iterations
    if not stored_hash.startswith(PBKDF2_SHA1_PREFIX):
        return False
    # Format: pbkdf2_sha1$iterations$salt$dk
    try:
        parts = stored_hash.split("$")
        if len(parts) != 4:
            return False
        _, iterations_str, salt_b64, dk_b64 = parts
        iterations = int(iterations_str)
        salt = _b64decode(salt_b64)
        dk = _b64decode(dk_b64)
        computed_dk = hashlib.pbkdf2_hmac(
            PBKDF2_SHA1_HASH_NAME,
            password.encode("utf-8"),
            salt,
            iterations,
            dklen=len(dk),
        )
        return hmac.compare_digest(computed_dk, dk)
    except Exception:
        return False


def register_password(password: str) -> str:
    """
    Hash a new user's password according to the current OWASP Password Storage Cheat Sheet policy.
    Uses Argon2id with recommended parameters.
    """
    # Use Argon2id for new hashes
    # argon2-cffi PasswordHasher automatically generates salt internally
    return _argon2id_hash(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt password against the stored hash.
    Supports all legacy formats and current format.
    """
    if not stored:
        return False

    # Detect format by prefix or pattern

    # Argon2id hashes start with "argon2id$"
    if stored.startswith(ARGON2ID_PREFIX):
        return _argon2id_verify(password, stored)

    # scrypt hashes start with "scrypt$"
    if stored.startswith(SCRYPT_PREFIX):
        return _scrypt_verify(password, stored)

    # pbkdf2_sha256 hashes start with "pbkdf2_sha256$"
    if stored.startswith(PBKDF2_PREFIX):
        return _pbkdf2_verify(password, stored)

    # pbkdf2_sha1 legacy hashes start with "pbkdf2_sha1$"
    if stored.startswith(PBKDF2_SHA1_PREFIX):
        return _pbkdf2_sha1_verify(password, stored)

    # bcrypt hashes start with $2a$, $2b$, or $2y$
    if _is_bcrypt_hash(stored):
        return _bcrypt_verify(password, stored)

    # Unknown format - reject
    return False
